+const form = document.querySelector("#support-form");
+const statusMessage = document.querySelector("#form-status");
+const fields = Array.from(form.querySelectorAll("input"));
+
+const messages = {
+  "full-name": "Enter your full name.",
+  email: "Enter a valid email address.",
+  phone: "Enter a phone number like +1 555-555-0123, or leave this optional field blank.",
+};
+
+let hasSubmitted = false;
+
+function errorIdFor(field) {
+  return `${field.id}-error`;
+}
+
+function getErrorMessage(field) {
+  if (field.validity.valueMissing) {
+    return messages[field.id];
+  }
+
+  if (field.validity.typeMismatch || field.validity.patternMismatch) {
+    return messages[field.id];
+  }
+
+  return "";
+}
+
+function setError(field, message) {
+  const id = errorIdFor(field);
+  const existingError = document.querySelector(`#${id}`);
+  const describedBy = new Set((field.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean));
+
+  if (!message) {
+    field.removeAttribute("aria-invalid");
+    describedBy.delete(id);
+    field.setAttribute("aria-describedby", Array.from(describedBy).join(" "));
+    existingError?.remove();
+    return;
+  }
+
+  field.setAttribute("aria-invalid", "true");
+  describedBy.add(id);
+  field.setAttribute("aria-describedby", Array.from(describedBy).join(" "));
+
+  if (existingError) {
+    existingError.textContent = message;
+    return;
+  }
+
+  const error = document.createElement("p");
+  error.id = id;
+  error.className = "field-error";
+  error.textContent = message;
+  field.insertAdjacentElement("afterend", error);
+}
+
+function validateField(field) {
+  const message = getErrorMessage(field);
+  setError(field, message);
+  return !message;
+}
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+  hasSubmitted = true;
+  statusMessage.textContent = "";
+
+  const firstInvalidField = fields.find((field) => !validateField(field));
+
+  if (firstInvalidField) {
+    firstInvalidField.focus();
+    return;
+  }
+
+  statusMessage.textContent = "Thanks. Your support request has been prepared.";
+  form.reset();
+  fields.forEach((field) => setError(field, ""));
+  hasSubmitted = false;
+});
+
+fields.forEach((field) => {
+  field.addEventListener("input", () => {
+    if (hasSubmitted) {
+      validateField(field);
+    }
+    statusMessage.textContent = "";
+  });
+});
+

')

